void DeskWindow::Capture(){if(!IsWindow(hwnd))return;RECT r{};GetWindowRect(hwnd,&r);auto& z=Model();z.x=r.left;z.y=r.top;z.width=r.right-r.left;if(!z.collapsed)z.height=r.bottom-r.top;MONITORINFOEXW mi{sizeof(mi)};GetMonitorInfoW(MonitorFromWindow(hwnd,MONITOR_DEFAULTTONEAREST),&mi);z.mon=mi.szDevice;z.mx=z.x-mi.rcWork.left;z.my=z.y-mi.rcWork.top;}
