fire_and_forget DeskWindow::Drop(DragEventArgs a,size_t position){auto deferral=a.GetDeferral();auto weak=winrt::make_weak(root);auto key=id;auto* controller=&owner;try{auto data=a.DataView();if(data.Contains(StandardDataFormats::StorageItems())){auto items=co_await data.GetStorageItemsAsync();auto it=std::find_if(controller->layout.zones.begin(),controller->layout.zones.end(),[&](auto const& z){return z.id==key;});if(it!=controller->layout.zones.end())for(auto const& item:items)if(!item.Path().empty())AddEntry(*it,std::wstring(item.Path()));}else if(data.Contains(StandardDataFormats::Text())){std::wstring text(co_await data.GetTextAsync());if(text.starts_with(L"guodesk-entry:"))controller->MoveEntry(text.substr(14),key,position);}if(auto live=weak.get())live.DispatcherQueue().TryEnqueue([controller]{controller->Refresh();controller->Save();});}catch(...){if(auto live=weak.get())MessageBoxW(nullptr,i18n::Tr(L"无法添加拖入项目。").c_str(),L"GuoDesk",MB_OK);}deferral.Complete();}
