void Controller::Start(){std::wstring warning;layout=store.Load(warning);i18n::SetLanguage(layout.settings.language);for(auto& z:layout.zones)if(!z.mappedFolder.empty())SyncMapped(z);for(auto& z:layout.zones){RECT r{z.x,z.y,z.x+z.width,z.y+z.height};Reanchor(r,z.mon,z.mx,z.my);z.x=r.left;z.y=r.top;}{auto& wg=layout.widgets;RECT rn{wg.noteX,wg.noteY,wg.noteX+wg.noteW,wg.noteY+wg.noteH};Reanchor(rn,wg.noteMon,wg.noteMX,wg.noteMY);wg.noteX=rn.left;wg.noteY=rn.top;RECT rt{wg.todoX,wg.todoY,wg.todoX+wg.todoW,wg.todoY+wg.todoH};Reanchor(rt,wg.todoMon,wg.todoMX,wg.todoMY);wg.todoX=rt.left;wg.todoY=rt.top;RECT rc{wg.clockX,wg.clockY,wg.clockX+wg.clockW,wg.clockY+wg.clockH};Reanchor(rc,wg.clockMon,wg.clockMX,wg.clockMY);wg.clockX=rc.left;wg.clockY=rc.top;RECT rm{wg.musicX,wg.musicY,wg.musicX+wg.musicW,wg.musicY+wg.musicH};Reanchor(rm,wg.musicMon,wg.musicMX,wg.musicMY);wg.musicX=rm.left;wg.musicY=rm.top;RECT rw{wg.weatherX,wg.weatherY,wg.weatherX+wg.weatherW,wg.weatherY+wg.weatherH};Reanchor(rw,wg.weatherMon,wg.weatherMX,wg.weatherMY);wg.weatherX=rw.left;wg.weatherY=rw.top;RECT rs{wg.searchX,wg.searchY,wg.searchX+560,wg.searchY+440};Reanchor(rs,wg.searchMon,wg.searchMX,wg.searchMY);wg.searchX=rs.left;wg.searchY=rs.top;}WNDCLASSW cls{};cls.lpfnWndProc=MessageProc;cls.hInstance=GetModuleHandleW(nullptr);cls.lpszClassName=L"GuoDesk.Controller";RegisterClassW(&cls);messageWindow=CreateWindowExW(WS_EX_TOOLWINDOW,cls.lpszClassName,L"GuoDesk Controller",WS_POPUP,0,0,0,0,nullptr,nullptr,cls.hInstance,this);taskbarCreated=RegisterWindowMessageW(L"TaskbarCreated");AddTray();for(auto const& z:layout.zones){windows.push_back(std::make_unique<DeskWindow>(*this,z.id));if(!z.mappedFolder.empty()){auto stamp=StampOf(z.mappedFolder);if(!stamp.empty())mappedStamp[PathKey(z.mappedFolder)]=stamp;}}if(!ApplyHotkey()&&!windows.empty())windows.front()->Notify(i18n::Tr(L"全局热键注册失败，可能已被其他程序占用。"));SetTimer(messageWindow,1,2000,nullptr);if(layout.widgets.noteVisible)note=std::make_unique<NoteWindow>(*this);if(layout.widgets.todoVisible)todo=std::make_unique<TodoWindow>(*this);if(layout.widgets.clockVisible)clockW=std::make_unique<ClockWindow>(*this);if(layout.widgets.musicVisible)music=std::make_unique<MusicWindow>(*this);if(layout.widgets.weatherVisible)weather=std::make_unique<WeatherWindow>(*this);Save();if(!layout.settings.guideDone)ShowGuide();if(!layout.settings.guideDone)ShowGuide();if(!warning.empty())MessageBoxW(nullptr,warning.c_str(),i18n::Tr(L"GuoDesk 配置恢复").c_str(),MB_OK|MB_ICONINFORMATION);}
void Controller::Save(){try{store.Save(layout);}catch(...){for(auto& w:windows)w->Notify(i18n::Tr(L"保存失败：请检查本地数据目录权限和剩余空间。 "));}}
void Controller::ImportLayout(Layout&& next){tidy.reset();note.reset();todo.reset();clockW.reset();music.reset();weather.reset();try{store.Save(next);}catch(...){for(auto& w:windows)w->Notify(i18n::Tr(L"保存失败：请检查本地数据目录权限和剩余空间。 "));return;}layout=std::move(next);i18n::SetLanguage(layout.settings.language);windows.clear();mappedStamp.clear();for(auto& z:layout.zones)if(!z.mappedFolder.empty())SyncMapped(z);for(auto& z:layout.zones){RECT r{z.x,z.y,z.x+z.width,z.y+z.height};Reanchor(r,z.mon,z.mx,z.my);z.x=r.left;z.y=r.top;}{auto& wg=layout.widgets;RECT rn{wg.noteX,wg.noteY,wg.noteX+wg.noteW,wg.noteY+wg.noteH};Reanchor(rn,wg.noteMon,wg.noteMX,wg.noteMY);wg.noteX=rn.left;wg.noteY=rn.top;RECT rt{wg.todoX,wg.todoY,wg.todoX+wg.todoW,wg.todoY+wg.todoH};Reanchor(rt,wg.todoMon,wg.todoMX,wg.todoMY);wg.todoX=rt.left;wg.todoY=rt.top;RECT rc{wg.clockX,wg.clockY,wg.clockX+wg.clockW,wg.clockY+wg.clockH};Reanchor(rc,wg.clockMon,wg.clockMX,wg.clockMY);wg.clockX=rc.left;wg.clockY=rc.top;RECT rm{wg.musicX,wg.musicY,wg.musicX+wg.musicW,wg.musicY+wg.musicH};Reanchor(rm,wg.musicMon,wg.musicMX,wg.musicMY);wg.musicX=rm.left;wg.musicY=rm.top;RECT rw{wg.weatherX,wg.weatherY,wg.weatherX+wg.weatherW,wg.weatherY+wg.weatherH};Reanchor(rw,wg.weatherMon,wg.weatherMX,wg.weatherMY);wg.weatherX=rw.left;wg.weatherY=rw.top;RECT rs{wg.searchX,wg.searchY,wg.searchX+560,wg.searchY+440};Reanchor(rs,wg.searchMon,wg.searchMX,wg.searchMY);wg.searchX=rs.left;wg.searchY=rs.top;}for(auto const& z:layout.zones){windows.push_back(std::make_unique<DeskWindow>(*this,z.id));if(!z.mappedFolder.empty()){auto stamp=StampOf(z.mappedFolder);if(!stamp.empty())mappedStamp[PathKey(z.mappedFolder)]=stamp;}}if(desktopMode)for(auto& w:windows)w->SetDesktop(true);if(layout.widgets.noteVisible)note=std::make_unique<NoteWindow>(*this);if(layout.widgets.todoVisible)todo=std::make_unique<TodoWindow>(*this);if(layout.widgets.clockVisible)clockW=std::make_unique<ClockWindow>(*this);if(layout.widgets.musicVisible)music=std::make_unique<MusicWindow>(*this);if(layout.widgets.weatherVisible)weather=std::make_unique<WeatherWindow>(*this);ApplySettings();if(!windows.empty())windows.front()->Notify(i18n::Tr(L"导入完成，界面已按新配置重建。"));}
void Controller::Add(){Zone zone;zone.id=NewId();zone.name=i18n::Tr(L"新分区");zone.x+=static_cast<int>(layout.zones.size())*30;zone.y+=static_cast<int>(layout.zones.size())*30;auto key=zone.id;layout.zones.push_back(std::move(zone));windows.push_back(std::make_unique<DeskWindow>(*this,key));if(desktopMode)windows.back()->SetDesktop(true);Save();}
void Controller::Remove(std::wstring const& key){auto it=std::find_if(layout.zones.begin(),layout.zones.end(),[&](auto const& z){return z.id==key;});if(it==layout.zones.end())return;auto index=static_cast<size_t>(it-layout.zones.begin());windows.erase(windows.begin()+index);layout.zones.erase(it);Save();}
void Controller::Refresh(){for(auto& w:windows)w->Refresh();}
void Controller::Show(){for(auto& w:windows)w->Show();if(windows.empty())Add();}
void Controller::HideAll(){for(auto& w:windows)if(IsWindowVisible(w->hwnd))ShowWindow(w->hwnd,SW_HIDE);}
void Controller::ToggleAll(){bool any=false;for(auto& w:windows)if(IsWindowVisible(w->hwnd)){any=true;break;}if(any)HideAll();else Show();}
bool Controller::ApplyHotkey(){if(messageWindow){UnregisterHotKey(messageWindow,1);UnregisterHotKey(messageWindow,2);}Hotkey hk;auto const& text=layout.settings.hotkey;if(!text.empty()&&ParseHotkey(text,hk))RegisterHotKey(messageWindow,1,hk.mods|MOD_NOREPEAT,hk.vk);Hotkey hs;auto const& stext=layout.settings.hotkeySearch;if(!stext.empty()&&ParseHotkey(stext,hs))return RegisterHotKey(messageWindow,2,hs.mods|MOD_NOREPEAT,hs.vk)!=0;return true;}
void Controller::Quit(){if(quitting)return;quitting=true;for(auto& w:windows)w->Capture();Save();Shell_NotifyIconW(NIM_DELETE,&tray);Application::Current().Exit();}
void Controller::ToggleDesktop(){desktopMode=!desktopMode;host=shell::DesktopHost();for(auto& w:windows)w->SetDesktop(desktopMode);}
